const config = { dry_run: true, max_attempts: 3, batch_size: 10, lease_minutes: 30, allowlisted_client_ids: [], cutoff_at_by_client: {} };
if (!config.allowlisted_client_ids.length) throw new Error('allowlist_required');
for (const id of config.allowlisted_client_ids) { if (!config.cutoff_at_by_client[id]) throw new Error('cutoff_required:' + id); }
return [{ json: config }];
